# Shared fixtures for the P5 catalog-currency units (test-catalog-currency.R).
#
# D3 law: every value produced here is fabricated (release labels under a
# reserved 9.x synthetic band, profile_count values 1/2/3, ids in the 9xx
# band). Nothing here encodes any COSMIC numeric content -- only structure
# and trivial synthetic counts. The committed golden fixture
# (fixtures/catalog-currency/downloads_page_synthetic.html) is generated by
# `.cc_page_text()` below, so fixture and constants cannot drift apart.
#
# All helpers are pure definitions -- loading this file has no side effects.

# Canonical cache/registry file names (the on-disk contract).
.CC_REF_FILE       <- "reference_data.json"
.CC_AVAIL_FILE     <- "availability_data.json"
.CC_RECORD_FILE    <- "record.rds"
.CC_CANDIDATE_FILE <- "candidate_registry.rds"
.CC_SOURCES_DIR    <- "sources"
.CC_REGISTRY_BASENAME <- "catalog_registry.rds"
.CC_FIXTURE_BASENAME  <- "downloads_page_synthetic.html"

# Synthetic source-document facts (must agree with the committed fixture --
# byte-locked by the fixture-golden test in test-catalog-currency.R).
.CC_FIXTURE_RELEASES <- c("9.9", "9.8", "9.7")
.CC_FIXTURE_AVAIL <- list(
  "9.9" = list("SBS-96" = c(GRCh37 = 3L, GRCh38 = 3L),
               "DBS-78" = c(GRCh37 = 2L),
               "ID-83"  = c(GRCh37 = 1L)),
  "9.8" = list("SBS-96" = c(GRCh37 = 2L)),
  "9.7" = list("SBS-96" = c(GRCh37 = 1L))
)

# Deterministic JSON builders (no external JSON dependency needed to WRITE:
# the payloads are simple enough to emit verbatim; the package-side reader
# is exercised against these texts).
.cc_reference_payload <- function(releases) {
  if (!is.character(releases) || length(releases) < 1L || !all(nzchar(releases))) {
    stop(".cc_reference_payload: releases must be a non-empty character vector",
         call. = FALSE)
  }
  items <- sprintf('{"id":%d,"version":"%s"}', seq_along(releases) + 900L, releases)
  paste0(
    '{"releases":{"human_cancer":[', paste(items, collapse = ","),
    '],"exposure":[],"cluster":[]},',
    '"genomes":{"GRCh37":{"id":1},"GRCh38":{"id":2}},',
    '"species":{"Human":{"id":3}}}'
  )
}

.cc_availability_payload <- function(entries) {
  if (!is.list(entries) || is.null(names(entries)) || !all(nzchar(names(entries)))) {
    stop(".cc_availability_payload: entries must be a named list", call. = FALSE)
  }
  rels <- vapply(names(entries), function(rel) {
    cls <- entries[[rel]]
    cls_json <- vapply(names(cls), function(cl) {
      builds <- cls[[cl]]
      cells <- sprintf('"%s":{"profile_count":%d}', names(builds), as.integer(builds))
      paste0('"', cl, '":{', paste(cells, collapse = ","), '}')
    }, character(1))
    paste0('"', rel, '":{', paste(cls_json, collapse = ","), '}')
  }, character(1))
  paste0('{"human_cancer":{', paste(rels, collapse = ","),
         '},"exposure":{},"cluster":{}}')
}

# Full synthetic downloads page: same structural carriers as the official
# page (two <script id=".." type="application/json"> blocks).
.cc_page_text <- function(reference_payload, availability_payload) {
  paste0(
    '<!doctype html>\n',
    '<!-- SYNTHETIC FIXTURE -- msuiter P5 catalog-currency tests (D3-safe).\n',
    '     Fabricated 9.x release labels and trivial profile_count values;\n',
    '     structure mirrors the official downloads page shape only. No COSMIC\n',
    '     numeric content is present or implied. -->\n',
    '<html lang="en">\n<head>\n',
    '  <title>SYNTHETIC downloads page (not COSMIC data -- test fixture)</title>\n',
    '</head>\n<body>\n',
    '  <h1>SYNTHETIC reference signatures download page</h1>\n',
    '  <script id="reference-data" type="application/json">', reference_payload, '</script>\n',
    '  <script id="availability-data" type="application/json">', availability_payload, '</script>\n',
    '</body>\n</html>\n'
  )
}

.cc_fixture_page <- function() {
  .cc_page_text(.cc_reference_payload(.CC_FIXTURE_RELEASES),
                .cc_availability_payload(.CC_FIXTURE_AVAIL))
}

.cc_fixture_path <- function() {
  test_path("fixtures", "catalog-currency", .CC_FIXTURE_BASENAME)
}

# Write text as raw bytes (no locale layer, no trailing-newline surprises).
.cc_write_bytes <- function(path, text) {
  dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
  con <- file(path, open = "wb")
  on.exit(close(con))
  writeBin(charToRaw(text), con)
  path
}

.cc_read_bytes <- function(path) {
  rawToChar(readBin(path, what = raw(), n = file.info(path)$size))
}

# Raw bytes for byte-for-byte comparison of BINARY artifacts (.rds files):
# rawToChar() would choke on embedded NULs, so comparisons go on raw vectors.
.cc_read_raw <- function(path) {
  readBin(path, what = raw(), n = file.info(path)$size)
}

# Fresh empty cache directory inside the session temp dir.
.cc_tmp_cache <- function(tag = "cache") {
  dir <- file.path(tempdir(), paste0("p5cc-", tag, "-", as.integer(Sys.time()),
                                     "-", sample.int(1e6, 1L)))
  dir.create(dir, recursive = TRUE, showWarnings = FALSE)
  dir
}

# Lay a synthetic source PAGE into a fresh dir and return its file path.
.cc_source_page <- function(tag = "src", releases = .CC_FIXTURE_RELEASES,
                             avail = .CC_FIXTURE_AVAIL, name = "page.html") {
  dir <- .cc_tmp_cache(paste0(tag, "-page"))
  path <- file.path(dir, name)
  .cc_write_bytes(path, .cc_page_text(.cc_reference_payload(releases),
                                       .cc_availability_payload(avail)))
  path
}

# Lay the canonical SPLIT-DIR source form (two bare JSON files).
.cc_source_dir <- function(tag = "src", releases = .CC_FIXTURE_RELEASES,
                           avail = .CC_FIXTURE_AVAIL) {
  dir <- .cc_tmp_cache(paste0(tag, "-dir"))
  .cc_write_bytes(file.path(dir, .CC_REF_FILE), .cc_reference_payload(releases))
  .cc_write_bytes(file.path(dir, .CC_AVAIL_FILE), .cc_availability_payload(avail))
  dir
}

# The committed registry object (already schema-validated by the reader).
.cc_committed_registry <- function() ms_catalog_registry()

# Derive a temp registry from the committed one by editing official-leg
# facts -- the canonical way tests simulate "registry pins something else"
# without duplicating the registry schema into the test suite.
.cc_registry_copy <- function(official_from_record = NULL, ...) {
  reg <- .cc_committed_registry()
  dots <- list(...)
  for (nm in names(dots)) reg[[nm]] <- dots[[nm]]
  if (!is.null(official_from_record)) {
    rec <- official_from_record
    if (!is.list(rec) || !identical(rec$kind, "catalog-currency-record")) {
      stop(".cc_registry_copy: official_from_record must be a catalog-currency record",
           call. = FALSE)
    }
    reg$official$documents <- lapply(rec$documents, function(d) {
      list(url = d$url, script_id = d$script_id, sha256 = d$sha256, bytes = d$bytes)
    })
    reg$official$releases <- rec$releases
    reg$official$latest_release <- rec$latest_release
    reg$official$structure_release <- rec$structure_release
    reg$official$structure <- rec$structure
  }
  path <- file.path(tempdir(), paste0("registry-", sample.int(1e6, 1L), ".rds"))
  saveRDS(reg, path, version = 2L)
  path
}

# Independent SHA-256 cross-check via the system tool (macOS shasum).
# Returns NULL when no tool is available so tests can skip the leg.
.cc_system_sha256 <- function(path) {
  tool <- Sys.which("shasum")
  if (!nzchar(tool)) return(NULL)
  out <- tryCatch(system2(paste(tool, "-a", "256", shQuote(path)), intern = TRUE),
                  error = function(e) NULL, warning = function(w) NULL)
  if (is.null(out) || !length(out)) return(NULL)
  dig <- sub("\\s.*$", "", out[1L])
  if (!grepl("^[0-9a-f]{64}$", dig)) return(NULL)
  dig
}
